package android.content; public class Context {public Object getAttributionSource(){return this;}public android.content.res.Resources getResources(){return new android.content.res.Resources();}public static final int MODE_PRIVATE=0;public static SharedPreferences settings=new SharedPreferences();public Context createDeviceProtectedStorageContext(){return this;}public SharedPreferences getSharedPreferences(String n,int m){return n.equals("settings")?settings:stores.computeIfAbsent(n,k->new SharedPreferences());}public android.content.pm.PackageManager getPackageManager(){return new android.content.pm.PackageManager();}public static java.util.Map<String,SharedPreferences> stores=new java.util.HashMap<>();public ClassLoader getClassLoader(){return getClass().getClassLoader();}public Context getApplicationContext(){return this;}public ContentResolver getContentResolver(){return new ContentResolver();}public Context createPackageContext(String name,int flags) throws android.content.pm.PackageManager.NameNotFoundException{return this;}}
